/* ---------- Stage 4: published reviews, never inferred live signals ---------- */
function stage4Reports() {
  var combined = ['A015','A102','A103','A104','A105','A106','A112'];
  var sessionOverrides = {A290:'2026-11-05',A494:'2026-11-09'};
  return (S.lib || []).filter(function(r) {
    return (r.cat === 'Gestión de posiciones' && /stage\s*4/i.test(r.title || '')) || combined.indexOf(r.id)>=0;
  }).map(function(r) { return { report:r, date:r.marketSession || sessionOverrides[r.id] || r.date }; })
    .sort(function(a,b) { return String(b.date).localeCompare(String(a.date)) || Number(/intrad[ií]a|intraday/i.test(a.report.title))-Number(/intrad[ií]a|intraday/i.test(b.report.title)) || Number(b.report.id.slice(1))-Number(a.report.id.slice(1)); });
}
function stage4Excerpt(r) {
  var text = String(r.text || ''), match = /## Decisión de gestión\s*\n([\s\S]*?)(?=\n## |$)/.exec(text);
  // Exact published excerpts, not a new assessment. No fabricated summary for older formats.
  return match ? match[1].trim() : '';
}
function vStage4() {
  ensureLib();
  var h='<header class="s4-hero"><p class="s4-eyebrow">'+esc(pt('GESTIÓN DE POSICIONES','POSITION MANAGEMENT'))+'</p><h2>Stage 4</h2><p>'+esc(pt('La revisión diaria del riesgo, los stops y los trailing. Último informe publicado y archivo de revisiones publicadas, sin confundir referencias con órdenes.','Daily risk, stop and trailing review. Latest published report and the published review archive, without confusing reference levels with orders.'))+'</p></header>';
  if(S.libState==='fail')return h+notice(pt('Informe no disponible','Report unavailable'),pt('No se pudo cargar la biblioteca. Recarga la página para intentarlo de nuevo.','The library could not load. Reload the page to try again.'));
  if(S.libState!=='ok')return h+'<p role="status">'+esc(t().lib.loading)+'</p>';
  var rows=stage4Reports();
  if(!rows.length)return h+notice(pt('Sin revisiones publicadas','No published reviews'),pt('Todavía no hay informes Stage 4 disponibles.','No Stage 4 reports are available yet.'));
  var latest=rows[0], chosen=S.stage4Sel ? rows.find(function(x){return x.report.id===S.stage4Sel;}) : latest;
  if(!chosen)return h+notice(pt('Informe no encontrado','Report not found'),pt('Ese identificador no corresponde a una revisión Stage 4 publicada.','That identifier is not a published Stage 4 review.'))+'<p><a class="btn" href="#stage4">'+esc(pt('Ver el último informe','View latest report'))+'</a></p>';
  var r=chosen.report, historic=r.id!==latest.report.id;
  h+='<section class="panel s4-latest"><div><p class="s4-eyebrow">'+esc(pt('ÚLTIMO INFORME PUBLICADO','LATEST PUBLISHED REPORT'))+'</p><h3><time datetime="'+esc(latest.date)+'">'+esc(fmtD(latest.date))+'</time> · '+esc(latest.report.id)+'</h3><p>'+esc(latest.report.title)+'</p></div><a class="btn" href="#stage4/'+esc(latest.report.id)+'">'+esc(pt('Abrir último','Open latest'))+'</a></section>';
  h+='<section class="s4-selector"><label for="stage4-date">'+esc(pt('Consultar otro día o revisión','Choose another day or review'))+'</label><select id="stage4-date">'+rows.map(function(x){return '<option value="'+esc(x.report.id)+'"'+(x.report.id===r.id?' selected':'')+'>'+esc(fmtD(x.date)+' · '+x.report.id+' · '+x.report.title)+'</option>';}).join('')+'</select><p>'+esc(pt('Solo se muestran informes publicados. Las fechas ausentes no tienen revisión disponible aquí; las revisiones parciales o intradía mantienen su título original.','Only published reports are shown. Missing dates have no review available here; partial and intraday reviews retain their original titles.'))+'</p></section>';
  h+='<aside class="stock-note s4-caution"><strong>'+esc(historic?pt('Consulta histórica: no son niveles vigentes.','Historical review: these are not current levels.'):pt('Revisión fechada, no monitorización en directo.','Dated review, not live monitoring.'))+'</strong><p>'+esc(pt('Stops manuales y trailing calculados son referencias de gestión. Este informe no acredita órdenes colocadas, ejecuciones ni precios garantizados del bróker. Cada regla conserva su condición de cierre o intradía.','Manual stops and calculated trailing levels are management references. This report does not establish broker orders, fills or guaranteed execution prices. Each rule retains its closing-price or intraday condition.'))+'</p></aside>';
  var excerpt=stage4Excerpt(r);
  if(excerpt)h+='<section class="panel s4-summary"><h3>'+esc(pt('Decisiones y alertas del informe seleccionado','Decisions and alerts from the selected report'))+'</h3><div>'+md(excerpt)+'</div></section>';
  h+='<article class="panel s4-report"><header><p class="s4-eyebrow">'+esc(historic?pt('ARCHIVO HISTÓRICO','HISTORICAL ARCHIVE'):pt('INFORME COMPLETO','FULL REPORT'))+'</p><h3>'+esc(r.title)+'</h3><p>'+esc(pt('Sesión / fecha de referencia: ','Session / reference date: ')+fmtD(chosen.date)+' · '+r.id)+'</p><a href="#biblioteca/'+esc(r.id)+'">'+esc(pt('Ver original en Biblioteca','View original in Library'))+'</a></header><div class="lib-text">'+md(r.text)+'</div></article>';
  return h;
}
